{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C12"],
      "claim": "Pentosan polysulfate, a highly sulfated polysaccharide, has oral bioavailability ≤3% in patients; the query is a sulfated glycosaminoglycan disaccharide with similar dense anionic/polar character, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C28"],
      "claim": "Dextran sulfate, another sulfated polysaccharide, shows poor oral bioavailability in humans, supporting low F for sulfated carbohydrate polymers.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C31"],
      "claim": "Zanamivir, a polar carbohydrate-like drug with multiple ionizable groups, has absolute oral bioavailability of 2% in healthy volunteers; the query shares the highly polar saccharide/ionizable motif, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C36"],
      "claim": "Acamprosate, an N-acetyl sulfonate, has absolute oral bioavailability of 11±1% in healthy volunteers, below the 20% threshold and supporting low F for N-acetyl/sulfonate polar molecules.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Glucoraphanin, a glycoside bearing a sulfate, has oral bioavailability of about 5% in humans, supporting low F for sulfated glycosides.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "A single older report suggested oral acetylcysteine bioavailability around 80%, but this is inconsistent with multiple controlled studies showing 4-10% and is too uncertain/outlier to outweigh the direct low-F analogues.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a highly polar, anionic sulfated glycosaminoglycan disaccharide. Direct oral bioavailability measurements for closely related sulfated polysaccharides (pentosan polysulfate ≤3%, dextran sulfate poor), polar carbohydrate drugs (zanamivir 2%), N-acetyl sulfonates (acamprosate 11%), and sulfated glycosides (glucoraphanin 5%) all fall below 20%. These high-transfer analogues overwhelmingly support low absolute oral bioavailability.",
  "evidence_gaps": [
    "No direct absolute oral bioavailability measurement exists for the exact query molecule.",
    "No permeability or transporter-mediated efflux data are available for the query specifically."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

